INSERT INTO `kpis` VALUES ('019f20a6-29f4-73ba-a458-a7466b9adb0f','Penguatan Brand Sekolah  Avicenna dengan mempublikasikan Fasilitas & Program rutin melalui website dan sosial media untuk mendukung Program dan Kegiatan Baru (Prioritas) pada T.P 2026-2027','(minimum 90% mencapai target digital publikasi) untuk mendukung ruang Inspirative Zone (ruang curhat, pojok inspirasi, mading interkatif, podcast & student led talkshow) & ruang transfomasi KB-TK','019f1cad-3ce9-7147-aa96-d1299f7d48cf','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-01-31','2026-07-01 12:26:28','2026-07-05 20:37:53',100.00),('019f214b-bab8-70c9-b0d2-94ba72093c97','Memiliki student success profile berdasarkan hasil wawancara Siswa & Orang Tua pada saat PPDB 2027-2028','Pada akhir T.P.2026/2027 100% calon siswa baru memiliki student success profile yang memuat tentang:\n\n1. Data potensi\n2. Minat bakat\n3. Gaya belajar\n4. Kepercayaan diri\n5. Kepribadian & karakter\n\nberdasarkan hasil wawancara Siswa & Orang Tua pada saat PPDB yang terdokumentasi dalam sistem PPDB.','019f1cad-3ce9-7147-aa96-d1299f7d48cf','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-07-31','2026-07-01 22:27:19','2026-07-05 20:43:49',100.00),('019f2151-4b4e-7201-a461-0cf43b891130','Meningkatkan citra Sekolah Avicenna sebagai sekolah yang Responsif, Proaktif, Solutif, dan Berorientasi Pelayanan','Meningkatkan citra Sekolah Avicenna sebagai sekolah yang Responsif, Proaktif, Solutif, dan Berorientasi Pelayanan dengan mencapai tingkat kepuasan orang tua dan siswa minimal 90% pada survei kepuasan layanan sekolah pada Juni 2027.','019f1cad-3ce9-7147-aa96-d1299f7d48cf','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-07-31','2026-07-01 22:33:23','2026-07-01 23:51:57',100.00),('019f2153-91a8-7108-850a-37df940cc25e','Mengimplementasikan Aplikasi Avicenna Pick Up Service pada 100% unit sekolah Avicenna untuk mendukung keamanan dan efisiensi penjemputan siswa','Mengimplementasikan Aplikasi Avicenna Pick Up Service pada 100% unit sekolah Avicenna untuk mendukung keamanan dan efisiensi penjemputan siswa pada Januari 2027.','019f1cad-0447-7281-ac27-d11e720e840c','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-01-31','2026-07-01 22:35:52','2026-07-01 23:53:51',100.00),('019f2155-7b67-717a-80b2-735fe87507fb','Terciptanya internet yang bermutu untuk proses pembelajaran dengan mengedepankan ketepatan, kecepatan dan keterbukaan Internet Management System','Terciptanya internet yang bermutu untuk proses pembelajaran dengan mengedepankan ketepatan, kecepatan dan keterbukaan system management internet pada T.P 2026/2027 untuk memudahkan Monitoring system bagi stakeholder (kepala sekolah serta guru-guru) 100% pada Agustus 2026','019f1cad-0447-7281-ac27-d11e720e840c','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-07-31','2026-07-01 22:37:58','2026-07-01 23:54:17',100.00),('019f2157-6428-7011-b2c8-1c6b6a1c1679','Mengembangkan Sistem PPDB Digital Intelligence yang terintegrasi  dengan Smart Quick Analytics, Smart Finder Student, dan  Virtual Admin','Mengembangkan Sistem PPDB Digital Intelligence yang terintegrasi \ndengan Smart Quick Analytics, Smart Finder Student, dan \nVirtual Admin sehingga 100% calon siswa memiliki \nStudent Success Profile digital dan seluruh data PPDB dapat \ndianalisis secara real-time pada Juni 2027.\n1. Smart Quick Analitik yang meliputi :\n    a. Analisa Potensi & Bakat\n    b. Analisa Tumbuh Kembang\n    c. Analisa Gaya Belajar\n    d. Analisa Pasar\n    e. Top 20 Hasil Test\n    f. Top 20 Nilai Raport\n\n2. Smart Finder Student (Hasil Analisa Berdasarkan Anak) :\n    a. Data Diri dan Orangtua (Tempat Kerja dan Penghasilan)\n    b. Ringkasan Akademik (Hasil Psikotest, Observasi, Litnum, \n         Wawancara Siswa, Wawancara Orangtua, Raport dan Prestasi)\n    c. RIngkasan Riwayat Kesehatan \n    d.Analisa Siswa (Analisa Minat & Bakat, Analisa Gaya Belajar, \n        Analisa Tumbuh Kembang)\n    e. Potensi Pengembangan Diri (Psikometri)\n\n3. Virtual Admin (Chat Bot)\n\n4. Form waiting list siswa, form daftar hadir sebelum event ppdb, \n    form keminatan masuk avicenna setelah event ppdb dan form \n    survei persektif positif dan kepuasan orangtua','019f1cad-0447-7281-ac27-d11e720e840c','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-06-30','2026-07-01 22:40:03','2026-07-01 23:55:26',100.00),('019f25bd-723e-7030-abc4-abcb0a48c4bc','Implementasi Monitoring System Internet Sekolah','Memudahkan Monitoring system bagi stakeholder (kepala sekolah serta guru-guru) 100% pada Agustus 2026','019f1cad-0447-7281-ac27-d11e720e840c','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2026-08-31','2026-07-02 19:10:00','2026-07-05 23:18:04',100.00),('019fb76b-e279-7199-a683-9389fbd5e219','WIG 1. Meningkatkan Employee Experience melalui penguatan layanan SDM sehingga Employee Satisfaction Score meningkat menjadi ???????85% dan Turnover Rate ???????5% pada Juni 2027.','Meningkatkan kualitas pengalaman kerja pegawai (Employee Experience) melalui penguatan layanan SDM yang responsif, profesional, dan berorientasi pada kebutuhan pegawai, sehingga tercipta lingkungan kerja yang positif, meningkatkan kepuasan pegawai (Employee Satisfaction Score ???????85%) serta menjaga tingkat turnover pegawai tetap rendah (Turnover Rate ???????5%) pada Juni 2027.','019f5a80-1854-70c3-953b-1dc587c7c806','019fb5e1-39b3-723b-bc11-7ebd37862ff6','2027-06-25','2026-07-31 02:05:28','2026-07-31 02:30:34',100.00),('019fc58e-4398-725a-9319-983b237e9213','Medical Checkup','Medical checkup tahunan','019f5a80-1854-70c3-953b-1dc587c7c806','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2026-10-31','2026-08-02 19:57:42','2026-08-02 19:57:42',100.00),('01a0655b-060d-7149-888e-2913ecf7bbf8','Meningkatkan pelaksanaan pelatihan eksternal dari 0 menjadi 2 pada juni 2027','Meningkatkan pelaksanaan pelatihan eksternal dari 0 menjadi 2 pada juni 2027','019f5a80-1854-70c3-953b-1dc587c7c806','019f1c70-2066-73a5-b6f0-fbf1fe4ae01a','2027-06-30','2026-09-02 20:40:59','2026-09-02 20:40:59',100.00),('01a0656e-cdde-7049-a31c-78bb483baeec','Meningkatkan jumlah modul LiM dari 0 pada Juni 2026 menjadi 12 pada Juni 2027',NULL,'019f5a83-5957-70ad-a6ac-cb3f3354b39f','019f5a9b-c212-72ab-b897-561f9d755fc5','2027-06-30','2026-09-02 21:02:35','2026-09-02 21:02:35',100.00),('01a06570-8673-722d-afdc-cc331a7c4439','Meningkatkan Employee Experience melalui penguatan layanan SDM dari 0% ke 85% pada Juni 2027',NULL,'019f5a80-1854-70c3-953b-1dc587c7c806','019f5a9b-858f-70d9-9c59-e678571a4a57','2027-07-30','2026-09-02 21:04:28','2026-09-02 21:04:28',100.00);
